  "Delta 2 Hz — deep sleep": { es: "Delta 2 Hz: sueño profundo", ar: "دلتا 2 هرتز — نوم عميق", zh: "Delta 2 Hz——深度睡眠", sw: "Delta 2 Hz — usingizi mzito", sv: "Delta 2 Hz — djup sömn", de: "Delta 2 Hz — Tiefschlaf", pt: "Delta 2 Hz — sono profundo", fr: "Delta 2 Hz — sommeil profond" },
  "Theta 6 Hz — drowsy, dreamy": { es: "Theta 6 Hz: somnoliento, soñador", ar: "ثيتا 6 هرتز — نعاس وأحلام", zh: "Theta 6 Hz——昏昏欲睡、如梦", sw: "Theta 6 Hz — kusinzia, kuota", sv: "Theta 6 Hz — dåsig, drömmande", de: "Theta 6 Hz — schläfrig, verträumt", pt: "Theta 6 Hz — sonolento, sonhador", fr: "Thêta 6 Hz — somnolent, rêveur" },
